    for(const auto &rootPath:c.libraries){if(!std::filesystem::is_directory(rootPath))fail("reference_c.compiler_inventory","Configured library directory is unavailable.");bool found=false;for(const auto &[p,sha]:hashes){(void)sha;const auto relative=p.lexically_relative(rootPath);if(!relative.empty()&&*relative.begin()!=L"..")found=true;}if(!found)fail("reference_c.compiler_inventory","Library directory has no locked files.");}
    std::size_t scanned=0;for(const auto *roots:{&c.includes,&c.libraries})for(const auto &rootPath:*roots)for(const auto &entry:std::filesystem::recursive_directory_iterator(rootPath)){if(++scanned>32768)fail("reference_c.compiler_inventory","Explicit compiler tree exceeds32768 entries.");const DWORD attrs=GetFileAttributesW(entry.path().c_str());if(attrs==INVALID_FILE_ATTRIBUTES||(attrs&FILE_ATTRIBUTE_REPARSE_POINT))fail("reference_c.compiler_inventory","Compiler search trees cannot contain reparse points or unreadable entries.");if(entry.is_regular_file()&&!hashes.contains(entry.path().lexically_normal()))fail("reference_c.compiler_inventory","Unlisted file in an admitted compiler search directory: "+utf8(entry.path()));}
