    std::string commandUtf16;for(const auto unit:command){const auto u=static_cast<std::uint16_t>(unit);commandUtf16+=static_cast<char>(u&255);commandUtf16+=static_cast<char>(u>>8);}commandUtf16.append(2,'\0');
