    SIZE_T attributeBytes=0;InitializeProcThreadAttributeList(nullptr,1,0,&attributeBytes);std::vector<unsigned char> attributes(attributeBytes);auto list=reinterpret_cast<LPPROC_THREAD_ATTRIBUTE_LIST>(attributes.data());if(!InitializeProcThreadAttributeList(list,1,0,&attributeBytes))systemFailure("Cannot initialize child handle whitelist");struct DeleteAttributes{LPPROC_THREAD_ATTRIBUTE_LIST p;~DeleteAttributes(){DeleteProcThreadAttributeList(p);}}deleteAttributes{list};HANDLE inherited[]{input.value,out.value,err.value};if(!UpdateProcThreadAttribute(list,0,PROC_THREAD_ATTRIBUTE_HANDLE_LIST,inherited,sizeof(inherited),nullptr,nullptr))systemFailure("Cannot whitelist child handles");
    Handle job(CreateJobObjectW(nullptr,nullptr));if(!job.valid())systemFailure("Cannot create child process job");JOBOBJECT_EXTENDED_LIMIT_INFORMATION limits{};limits.BasicLimitInformation.LimitFlags=JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE|JOB_OBJECT_LIMIT_PROCESS_MEMORY;limits.ProcessMemoryLimit=512U*1024U*1024U;if(!SetInformationJobObject(job.value,JobObjectExtendedLimitInformation,&limits,sizeof(limits)))systemFailure("Cannot bound child job");
