    if(!CreateProcessW(exe.c_str(),command.data(),nullptr,nullptr,TRUE,CREATE_SUSPENDED|CREATE_NO_WINDOW|CREATE_UNICODE_ENVIRONMENT|EXTENDED_STARTUPINFO_PRESENT,block.data(),directory.c_str(),&startup.StartupInfo,&pi))systemFailure("Cannot launch exact child executable");Handle child(pi.hProcess),thread(pi.hThread);if(!AssignProcessToJobObject(job.value,child.value)){TerminateProcess(child.value,1);systemFailure("Cannot contain child process tree");}if(ResumeThread(thread.value)==static_cast<DWORD>(-1)){TerminateJobObject(job.value,1);systemFailure("Cannot start contained child");}
