void compile(const Compiler&c,const std::filesystem::path&directory,std::vector<std::filesystem::path>&artifacts){
    if(!c.state)fail("reference_c.compiler_missing","No immutable admitted compiler configuration.");auto result=process(c.executable,{L"/nologo",L"/std:c17",L"/MT",L"/fp:strict",L"/O2",L"/utf-8",L"/c",L"/Fo"+(directory/L"kernel.obj").wstring(),(directory/L"kernel.c").wstring()},directory,c,30000);if(result.exit)fail("reference_c.compile_failed","Exact C17 compiler refused the program: "+excerpt(result.output)+excerpt(result.error));
    artifacts.insert(artifacts.end(),result.artifacts.begin(),result.artifacts.end());std::vector<std::wstring> args{L"/NOLOGO",L"/MACHINE:X64",L"/SUBSYSTEM:CONSOLE",L"/INCREMENTAL:NO",L"/OUT:"+(directory/L"kernel.exe").wstring(),(directory/L"kernel.obj").wstring(),L"kernel32.lib"};for(const auto&p:c.libraries)args.push_back(L"/LIBPATH:"+p.wstring());result=process(c.linker,args,directory,c,30000);if(result.exit)fail("reference_c.link_failed","Exact C17 linker refused the program: "+excerpt(result.output)+excerpt(result.error));artifacts.insert(artifacts.end(),result.artifacts.begin(),result.artifacts.end());(void)fileHash(directory/L"kernel.exe");
}
